import{text,list,identifiers,choice}from'../creative-kit/state.js?v=0.14.0';
export const FIELDS=['title','mechanism','benefit','ingredients','changed','why','test'];
export const node=id=>({id,parents:[],sources:[],title:'New concept',mechanism:'',benefit:'',ingredients:'',changed:'',why:'',test:'',parked:false});
export function make(id='first',example='example'){const n=node('n1');if(example!=='blank')Object.assign(n,{title:'A shared decision briefing',mechanism:'Give the next decision owner a short view of commitments, uncertainty and remaining options.',benefit:'Keep context intact when a battery decision changes hands.',ingredients:'A written briefing; a named owner; explicit unknowns.',changed:'Starting concept.',why:'Important context gets lost between roles.',test:'Walk one fictional battery decision through two shift changes.'});const w={id,problem:example==='blank'?'':'How might a battery decision retain context across a handoff?',nodes:[n],compare:['n1',null]};if(example!=='blank'){const n2={...node('n2'),parents:['n1'],sources:[{id:'n1',title:n.title,mechanism:n.mechanism}],title:'A five-minute rehearsal',mechanism:'People rehearse the next decision together and name what could change it.',benefit:n.benefit,ingredients:'Two roles; a scenario; a five-minute conversation.',changed:'Replace a static briefing with a rehearsal.',why:'Testing understanding may expose gaps that a document conceals.',test:'Compare the next owner’s explanation after reading versus rehearsing.'};w.nodes.push(n2);w.compare[1]='n2';}return w;}
export function validate(w){list(w.nodes,24);if(!w.nodes.length)throw Error('Keep at least one concept.');identifiers(w.nodes);const seen=new Set();for(const n of w.nodes){FIELDS.forEach(f=>text(n[f]));list(n.parents,2);if(new Set(n.parents).size!==n.parents.length||n.parents.some(id=>!seen.has(id)))throw Error('Parents must precede their descendants.');list(n.sources,2);if(n.sources.length!==n.parents.length)throw Error('Ancestry snapshot is incomplete.');n.sources.forEach((s,i)=>{if(s.id!==n.parents[i])throw Error('Ancestry snapshot is inconsistent.');text(s.title);text(s.mechanism);});if(typeof n.parked!=='boolean')throw Error('Invalid concept status.');seen.add(n.id);}if(!Array.isArray(w.compare)||w.compare.length!==2||w.compare.some(id=>id!==null&&!seen.has(id))||(w.compare[0]&&w.compare[0]===w.compare[1]))throw Error('Choose two different concepts.');return w;}
export function depth(w,id){const n=w.nodes.find(x=>x.id===id);return n.parents.length?1+Math.max(...n.parents.map(p=>depth(w,p))):0;}
export function apply(w,a){if(a.type==='edit'){const n=w.nodes.find(x=>x.id===a.item);if(!n)throw Error('Concept is missing.');choice(a.field,FIELDS);n[a.field]=text(a.value);}else if(a.type==='fork'||a.type==='combine'){const parents=a.type==='fork'?[a.parent]:w.compare.filter(Boolean);if(a.type==='combine'&&parents.length!==2)throw Error('Choose two concepts to combine.');const src=parents.map(id=>w.nodes.find(n=>n.id===id));if(src.some(n=>!n))throw Error('Parent is missing.');const n=node(a.id);Object.assign(n,{parents,sources:src.map(s=>({id:s.id,title:s.title,mechanism:s.mechanism})),title:a.type==='fork'?`${src[0].title} · variation`:'A combination to develop',mechanism:a.type==='fork'?src[0].mechanism:'',benefit:src.map(s=>s.benefit).join('\n'),ingredients:src.map(s=>s.ingredients).join('\n'),changed:a.type==='fork'?'':'Which parts from each parent will this retain?'});w.nodes.push(n);}else if(a.type==='compare'){const slot=Number(a.slot);if(![0,1].includes(slot)||!w.nodes.some(n=>n.id===a.id))throw Error('Choose a concept and comparison slot.');if(w.compare[1-slot]===a.id)w.compare[1-slot]=null;w.compare[slot]=a.id;}else if(a.type==='clear')w.compare[Number(a.slot)]=null;else if(a.type==='park'){const n=w.nodes.find(n=>n.id===a.id);if(!n)throw Error('Concept is missing.');n.parked=!n.parked;}else if(a.type==='remove'){if(w.nodes.length===1||w.nodes.some(n=>n.parents.includes(a.id)))throw Error('Keep concepts with descendants; park them instead.');w.nodes=w.nodes.filter(n=>n.id!==a.id);w.compare=w.compare.map(id=>id===a.id?null:id);}else if(a.type==='root')w.nodes.push(node(a.id));else throw Error('Unknown family action.');}
export function markdown(w){return ['# Idea family tree','',w.problem,'','Children preserve the source wording at creation; later parent edits do not flow into them.','',...w.nodes.flatMap(n=>[`## ${n.title}${n.parked?' · parked':''}`,'',`Parents: ${n.sources.map(s=>s.title).join(' + ')||'Original concept'}`,'',...FIELDS.slice(1).flatMap(f=>[`**${f}**`,n[f]||'_Not written._','']),...n.sources.flatMap(s=>[`Source snapshot — ${s.title}:`,s.mechanism,''])])].join('\n');}
